mapper.select:
SELECT PROD_NUM, PROD_CODE, PROD_NAME, PROD_PRICE, MANUFACTURER, REG_DATE
FROM PRODUCT_INFO
WHERE PROD_NUM = #{prodNum}

mapper.update:
UPDATE PRODUCT_INFO
SET PROD_CODE     = #{prodCode},
    PROD_NAME     = #{prodName},
    PROD_PRICE    = #{prodPrice},
    MANUFACTURER  = #{manufacturer}
WHERE PROD_NUM = #{prodNum}
